<?php
declare(strict_types=1);if(PHP_SAPI!=='cli')exit;
// Explicitly remove only obsolete workbook content; other business tables remain intact.
$home=dirname(__DIR__,2);if(isset($argv[2]))$home=$argv[2];$home=realpath($home);if(!$home||!is_dir($home.'/thevictor-private'))throw new RuntimeException('Invalid account root.');
$live=realpath($home.'/thevictor-private/orders.sqlite');$paths=[];foreach(glob($home.'/*backup*',GLOB_ONLYDIR) as $dir)foreach(glob($dir.'/*.sqlite') as $p)$paths[]=$p;foreach(glob($home.'/thevictor-private/backups/*.sqlite') as $p)$paths[]=$p;$paths[]=$live;
$apply=($argv[1]??'')==='apply';$before=0;$after=0;$files=0;
foreach(array_unique($paths) as $path){$real=realpath($path);if(!$real||!str_starts_with($real,$home.'/')||is_link($path))throw new RuntimeException('Unsafe backup path.');$isLive=$real===$live;$db=new PDO('sqlite:'.$real,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('PRAGMA busy_timeout=15000');$tables=$db->query("SELECT name FROM sqlite_master WHERE type='table'")->fetchAll(PDO::FETCH_COLUMN);$purge=['staff_workbook_history','workbook_cell_events','workbook_input_issues','workbook_product_checks','workbook_row_times'];if(!$isLive)$purge=array_merge($purge,['staff_workbook','google_sync_sheets','google_sync_state','workbook_sheet_years']);
 $before+=filesize($real);if($apply){$guard=$isLive?$db->query('SELECT version||":"||length(snapshot) FROM staff_workbook WHERE id=1')->fetchColumn():null;$db->beginTransaction();foreach($purge as $t)if(in_array($t,$tables,true))$db->exec('DELETE FROM "'.$t.'"');$db->commit();$db->exec('PRAGMA wal_checkpoint(TRUNCATE)');$db->exec('VACUUM');if($isLive&&$guard!==$db->query('SELECT version||":"||length(snapshot) FROM staff_workbook WHERE id=1')->fetchColumn())throw new RuntimeException('Current workbook changed during maintenance; inspect.');}$db=null;clearstatcache(true,$real);$after+=filesize($real);$files++;
}
echo json_encode(['applied'=>$apply,'databases'=>$files,'beforeBytes'=>$before,'afterBytes'=>$after,'freedBytes'=>$before-$after]).PHP_EOL;
